// Let's inspect the vehicles currently shown on the search results page
const vehicles = await browserjs(tabId, () => {
  // Carvana vehicle cards typically have data-qa="vehicle-card" or similar, or article elements
  const cards = Array.from(document.querySelectorAll('[data-qa="vehicle-card"], [data-testid="vehicle-card"], article, .vehicle-card'));
  if (cards.length > 0) {
    return cards.map(c => ({
      text: c.innerText.slice(0, 300),
      links: Array.from(c.querySelectorAll('a')).map(a => a.href)
    }));
  }
  // Fallback: look for text containers
  const items = Array.from(document.querySelectorAll('a[href*="/vehicle/"]'));
  return items.map(a => ({
    href: a.href,
    text: a.innerText
  }));
});

