// Let's inspect the cards and their text content
const cardDetails = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll('a[href*="/vehicle/"]'));
  return links.map(a => {
    // find closest container
    let p = a.parentElement;
    for (let i = 0; i < 5; i++) {
      if (p && p.innerText && p.innerText.includes("$")) break;
      if (p && p.parentElement) p = p.parentElement;
    }
    return {
      href: a.href,
      text: p ? p.innerText : ""
    };
  });
});

console.log("Found links count:", cardDetails.length);
