const uniqueMap = new Map();
for (const item of cardDetails) {
  if (!uniqueMap.has(item.href) || uniqueMap.get(item.href).length < item.text.length) {
    uniqueMap.set(item.href, item.text);
  }
}

console.log("Unique vehicles count:", uniqueMap.size);
for (const [href, text] of uniqueMap.entries()) {
  console.log("---", href);
  console.log(text.split("\n").slice(0, 8).join(" | "));
}

