  for (const a of links) {
    const id = a.href.split("?")[0];
    if (!seen.has(id)) {
      seen.add(id);
      let p = a;
      for (let i = 0; i < 5; i++) {
        if (p && p.innerText && p.innerText.includes("$")) break;
        if (p && p.parentElement) p = p.parentElement;
      }
      list.push({ href: id, text: p ? p.innerText.replace(/\n+/g, " | ") : "" });
    }
  }
  return list;
});
