const tabId = 343605414;

const vehicleData = await browserjs(tabId, () => {
  // Let's get the full vehicle details
  const title = document.querySelector('h1')?.innerText || document.title;

  // Look for price
  const priceEls = Array.from(document.querySelectorAll('*')).filter(el => el.children.length === 0 && /\$\d{1,3}(,\d{3})*/.test(el.innerText));
  const prices = priceEls.map(el => el.innerText.trim()).slice(0, 10);

  // Look for mileage
  const mileageEls = Array.from(document.querySelectorAll('*')).filter(el => el.children.length === 0 && /\b\d{1,3}(,\d{3})*\s*miles\b/i.test(el.innerText));
  const mileages = mileageEls.map(el => el.innerText.trim());

  // Look for features section
  const features = Array.from(document.querySelectorAll('li, [data-qa*="feature"], [data-testid*="feature"]'))
    .map(el => el.innerText.trim())
    .filter(t => t.length > 0 && t.length < 80);

  // Check page text for key terms
  const bodyText = document.body.innerText;
  const hasCarPlay = /apple\s*carplay/i.test(bodyText);
  const hasACC = /adaptive\s*cruise\s*control/i.test(bodyText);
  const hasBlindSpot = /blind\s*spot/i.test(bodyText);

  return {
    title,
    prices: [...new Set(prices)],
    mileages: [...new Set(mileages)],
    hasCarPlay,
    hasACC,
    hasBlindSpot,
    featureCount: features.length,
    featuresSample: features.slice(0, 30)
  };
});

